/** Writes docs/KS2_COVERAGE.md from the outcome map: every Key Stage 2 outcome, the topics behind it, and what's left. */
import { writeFileSync } from "node:fs";
import { SKILL_BY_ID } from "../src/curriculum";
import { KS2_OUTCOMES } from "../src/curriculum/ks2-outcomes";

const full = KS2_OUTCOMES.filter((o) => o.cover === "full").length;
const out = [
  "# Key Stage 2 coverage",
  "",
  "Generated by `npm run ks2-coverage` from `src/curriculum/ks2-outcomes.ts`. Each National Curriculum outcome is paraphrased and mapped to the topics that practise it. Checked by `ks2-outcomes.test.ts`.",
  "",
  `**${KS2_OUTCOMES.length} outcomes: ${full} fully covered, ${KS2_OUTCOMES.length - full} partly.** Still needs a teacher's review of the mapping.`,
  "",
];
for (const year of [3, 4, 5, 6] as const) {
  out.push(`## Year ${year}`, "", "| Outcome | Topics | Covered |", "| --- | --- | --- |");
  for (const o of KS2_OUTCOMES.filter((x) => x.year === year)) out.push(`| ${o.strand}: ${o.text} | ${o.skills.map((id) => SKILL_BY_ID[id].name).join("; ")} | ${o.cover === "full" ? "Yes" : `Partly. ${o.note}`} |`);
  out.push("");
}
writeFileSync(new URL("../docs/KS2_COVERAGE.md", import.meta.url), out.join("\n"));
console.log(`${KS2_OUTCOMES.length} outcomes, ${full} full`);
